# variant 2067
@torch.no_grad()
def generate_greedy(model, input_ids, max_new_tokens=50, eos_id=3):
 for _ in range(max_new_tokens):
 logits = model(input_ids).logits[:, -1, :]
 next_token = logits.argmax(dim=-1, keepdim=True)
